    if (num &lt;= 1) return 1;
    let res = 1;
    for (let i = 2; i &lt;= num; i++) res *= i;
    return res;
  };

  const getPermutations = (arr, k) =&gt; {
    let results = [];
    const backtrack = (current) =&gt; {
      if (current.length === k) {
        results.push([...current]);
        return;
      }
      for (let i = 0; i &lt; arr.length; i++) {
        if (!current.includes(arr[i])) {
          current.push(arr[i]);
          backtrack(current);
          current.pop();
        }
      }
    };
    backtrack([]);
    return results;
  };

  const getCombinations = (arr, k) =&gt; {
    let results = [];
    const backtrack = (start, current) =&gt; {
      if (current.length === k) {
        results.push([...current]);
        return;
      }
      for (let i = start; i &lt; arr.length; i++) {
        current.push(arr[i]);
        backtrack(i + 1, current);
        current.pop();
      }
    };
    backtrack(0, []);
    return results;
  };

  const permutations = useMemo(() =&gt; getPermutations(items, r), [n, r]);
  const combinations = useMemo(() =&gt; getCombinations(items, r), [n, r]);

