        items.forEach((item) =&gt; {
          if (!currentPath.includes(item)) {
            const child = { name: item, children: [] };
            node.children.push(child);
            build(child, [...currentPath, item], depth + 1);
          }
        });
      } else {
        for (let i = startIdx; i &lt; items.length; i++) {
          const child = { name: items[i], children: [] };
          node.children.push(child);
          build(child, [...currentPath, items[i]], depth + 1, i + 1);
        }
      }
    };
    build(root, [], 0);
    return root;
  };

  const pTree = useMemo(() =&gt; generateTreeData(&#39;permutation&#39;), [n, r]);
  const cTree = useMemo(() =&gt; generateTreeData(&#39;combination&#39;), [n, r]);

