                  x={0} 
                  y={0} 
                  spacing={spacing * 0.5} 
                  depth={depth + 1} 
                  colorClass={colorClass}
                /&gt;
              &lt;/g&gt;
            &lt;/React.Fragment&gt;
          );
        })}
      &lt;/g&gt;
    );
  };

  return (
