          &lt;div className=&quot;flex items-center gap-2 mb-6 text-indigo-600 font-bold uppercase tracking-wider text-sm&quot;&gt;
            &lt;Settings size={20} /&gt;
            &lt;span&gt;Setup&lt;/span&gt;
          &lt;/div&gt;

          &lt;div className=&quot;space-y-8&quot;&gt;
            &lt;div&gt;
              &lt;label className=&quot;block text-sm font-medium mb-2&quot;&gt;Total Elements ($n$): {n}&lt;/label&gt;
              &lt;input 
                type=&quot;range&quot; min=&quot;1&quot; max=&quot;5&quot; value={n} 
                onChange={(e) =&gt; {
                  const val = parseInt(e.target.value);
                  setN(val);
                  if (r &gt; val) setR(val);
                }}
                className=&quot;w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600&quot;
              /&gt;
              &lt;div className=&quot;flex gap-2 mt-3 flex-wrap&quot;&gt;
                {items.map((item, i) =&gt; (
                  &lt;span key={i} className=&quot;text-2xl bg-slate-100 p-2 rounded-lg&quot;&gt;{item}&lt;/span&gt;
                ))}
              &lt;/div&gt;
            &lt;/div&gt;

            &lt;div&gt;
              &lt;label className=&quot;block text-sm font-medium mb-2&quot;&gt;Subset Size ($r$): {r}&lt;/label&gt;
              &lt;input 
                type=&quot;range&quot; min=&quot;1&quot; max={n} value={r} 
                onChange={(e) =&gt; setR(parseInt(e.target.value))}
                className=&quot;w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600&quot;
              /&gt;
            &lt;/div&gt;

            &lt;div className=&quot;space-y-4 pt-4 border-t border-slate-100&quot;&gt;
              &lt;div className=&quot;flex justify-between items-center p-3 bg-blue-50 rounded-xl border border-blue-100&quot;&gt;
                &lt;div className=&quot;flex items-center gap-2 text-blue-700 font-bold&quot;&gt;
                  &lt;ListOrdered size={18} /&gt;
                  &lt;span&gt;$P(n,r)$&lt;/span&gt;
                &lt;/div&gt;
                &lt;span className=&quot;text-xl font-mono font-bold text-blue-800&quot;&gt;{nPr}&lt;/span&gt;
              &lt;/div&gt;
              &lt;div className=&quot;flex justify-between items-center p-3 bg-emerald-50 rounded-xl border border-emerald-100&quot;&gt;
                &lt;div className=&quot;flex items-center gap-2 text-emerald-700 font-bold&quot;&gt;
                  &lt;Shapes size={18} /&gt;
                  &lt;span&gt;$C(n,r)$&lt;/span&gt;
                &lt;/div&gt;
                &lt;span className=&quot;text-xl font-mono font-bold text-emerald-800&quot;&gt;{nCr}&lt;/span&gt;
              &lt;/div&gt;
            &lt;/div&gt;
          &lt;/div&gt;
        &lt;/section&gt;

        {/* Tree Comparison Area */}
        &lt;section className=&quot;lg:col-span-3 space-y-6&quot;&gt;
          &lt;div className=&quot;grid grid-cols-1 md:grid-cols-2 gap-6&quot;&gt;

            {/* Permutation Tree */}
            &lt;div className=&quot;bg-white p-6 rounded-2xl shadow-sm border border-slate-200&quot;&gt;
